head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[selectbox > P > renderType]<br/>SelectBox 컴포넌트가 렌더링 되는 방식을 설정합니다.",
    "validation" : [
        "미설정 시 모바일 웹브라우저이면 'native' 로 적용되고, 그렇지 않으면 'component' 로 적용됩니다.",
        "component 설정 시 table 태그를 갖는 div 태그로 렌더링됩니다.",
        "native 설정 시 select 태그를 갖는 두 개의 중첩 div 태그로 렌더링됩니다.",
        "native 설정 시 아이템은 select 태그 하위에 option 태그로 정의됩니다.",
        "select 설정 시 select 태그로 렌더링되며 아이템은 select 태그 하위에 option 태그로 정의됩니다.",
        "auto 설정 시 모바일 웹브라우저이면 'native' 로 적용되고, 그렇지 않으면 'component' 로 적용됩니다.",
        "렌더링 되는 태그에 따라 'w2selectbox', 'w2selectbox_native', 'w2selectbox_select', 'w2selectbox_row', 'w2selectbox_native_select' 등의 클래스가 추가됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {
        renderType : con_renderType.getText(),        
    }

    let cList = $c.gcm.createCList(properties)

    // comp 생성 함수 호출
    $c.gcm.createBasicSelectBox(cList);
}



scwin.btn_getRenderType_onclick = function (e) {
    let rtn = '';

    rtn = target1.render.tagName;        
    wf_body_bottom.getObj("scwin").setReturnValue("Main tagName : " + rtn);

    rtn = target1.render.className;
    wf_body_bottom.getObj("scwin").setReturnValue("Main className : " + rtn);

    // id가 "target1"을 포함하는 모든 요소 찾기
    let matchingElements = document.querySelectorAll('[id*="target1"]');

    matchingElements.forEach(function(element) {
        let childElements = element.querySelectorAll("*"); // 모든 하위 요소 선택

        // 하위 요소들의 태그명 출력
        childElements.forEach(function(child) {
            rtn = child.tagName;
            wf_body_bottom.getObj("scwin").setReturnValue("Child tagName : " + rtn);

            rtn = child.className;
            wf_body_bottom.getObj("scwin").setReturnValue("Child className : " + rtn);
        });
    });
};
